// ║ ║                                                                                 ║ ║                              ║
/// The absolute apex entry point for the CPI-SI Substrate SDK.                      ║ ║                              ║
/// This function acts purely as a dispatcher, handing off execution to the          ║ ║                              ║
/// `app` orchestrator module which manages the GUI/CLI lifecycle.                   ║ ║                              ║
fn main() {                                                                         // ║ ║                              ║
    println!("--- CPI-SI Substrate SDK [v{}] ---", get_version());                  // ║ ║                              ║
// ║ ║                                                                                 ║ ║                              ║
    match app::bootstrap() {                                                        // ║ ║                              ║
        Ok(viewport) => {                                                           // ║ ║                              ║
            app::run(&viewport);                                                    // ║ ║                              ║
            app::teardown();                                                        // ║ ║                              ║
        }                                                                           // ║ ║                              ║
        Err(e) => {                                                                 // ║ ║                              ║
            eprintln!("CRITICAL FAILURE: {}", e);                                   // ║ ║                              ║
            std::process::exit(1);                                                  // ║ ║                              ║
        }                                                                           // ║ ║                              ║
    }                                                                               // ║ ║                              ║
}                                                                                   // ║ ║                              ║
